// Typed access to the guidance cards generated by scripts/build-content.ts.
// The JSON sits at ../generated/cards.json relative to this module in both src/
// and dist/, so the same URL works before and after compilation.
import { readFileSync } from 'node:fs';

export type Card = { id: string; rules: string[]; source: string; next?: string; description?: string; full?: string };

type StoredCard = Omit<Card, 'id'>;
type CardsFile = { flow_version: string; tag: string; commit: string; repo: string; modules: string[]; cards: Record<string, StoredCard> };

function load(): CardsFile {
  const data = JSON.parse(readFileSync(new URL('../generated/cards.json', import.meta.url), 'utf8')) as Partial<CardsFile>;
  if (typeof data.flow_version !== 'string' || typeof data.tag !== 'string' || !Array.isArray(data.modules) || !data.cards) {
    throw new Error('generated/cards.json is malformed: run node scripts/build-content.ts');
  }
  return data as CardsFile;
}

const data = load();

export const FLOW_VERSION: string = data.flow_version;
export const FLOW_TAG: string = data.tag;
export const MODULES: readonly string[] = Object.freeze([...data.modules]);

export function getCard(id: string): Card | undefined {
  if (!Object.hasOwn(data.cards, id)) return undefined;
  const stored = data.cards[id] as StoredCard;
  return { id, ...stored, rules: [...stored.rules] };
}

export function cardRules(id: string): string[] {
  return getCard(id)?.rules ?? [];
}

export function cardIds(): string[] {
  return Object.keys(data.cards);
}
